                    for channel in CHANNELS[:3]:
                        advertising[channel][g] = 800 if raw < .8 else 1500
                else:
                    rate, channel, last_budget = performance[0]
                    source = [r for r in stats["cohorts"] if r["group_id"] == g and r["source"] == channel]
                    paid_revenue = sum(r["mrr"] for r in source if r["status"] == "subscribed")
                    efficiency = paid_revenue / max(1,last_budget * 7)
                    # Occupancy and realized spend efficiency both taper marginal acquisition.
                    rough_stock = m["subs"] / max(cap,250)
                    maximum = max(7000, min(260000, cap * (1.75 if g=="S1" else 1.13)))
                    if rough_stock > .94:
                        maximum *= max(.18, 1.0-(rough_stock-.94)*1.40)
                    if efficiency >= 2.0:
                        budget = max(3500, last_budget * (1.55 if efficiency > 4 else 1.28))
                    elif efficiency < .48 and last_budget >= 2500:
                        budget = max(700, last_budget*.39)
                    elif efficiency >= .75:
                        budget = max(1800, last_budget*.94)
                    else:
                        budget = max(900, last_budget*.68)
                    if day >= 470 and efficiency >= 1.3 and rough_stock < 1:
                        budget *= 1.17
                    advertising[channel][g] = round(min(budget,maximum)/100)*100
                    forecasts[g] = round(efficiency, 2)
        else:
            if g in ("E1","E2","E3"):
                base = {"E1": 21, "E2": 55, "E3": 58}[g]
            else:
                base = min(140,max(15,wtp*.63))
            plan = "C"
            if raw > 1.75 or (g == "E1" and raw >= 1.02):
                plan = "B"
            if raw > 2.55 and (wtp < 115 or m["seats"] > 180000):
                plan = "A"
            if g == "E1":
                base = 20 if raw < 1.30 else 24 if raw < 2.1 else 27
            elif g in ("E2", "E3"):
                base += min(25, max(0, (raw-1.45)*19))
            enterprise[g] = (plan,round(base,2))
            ads_strength[g] = .35 if raw >= 2.7 else 0
            pipeline = sum(r["n"] for r in stats["enterprise"] if r["group_id"] == g and r["close_reason"] == "")
            if "D_" in g and raw > .82 and m["subs"] < .72*cap and pipeline < max(18, .16*cap):
                advertising["linkedin"][g] = min(3800, max(700, round(cap*6/100)*100))

    last_usage = max((r["total_usage_units"] for r in stats["service"]), default=100000)
    projected_usage = last_usage * (1.50 if day < 77 else 1.19)
    if projected_usage > 260000000:
        quotas = {"A":145,"B":165,"C":210}
    if projected_usage > 350000000:
        factor = 280000000 / projected_usage
        quotas = {p:max(60,round(q*factor)) for p,q in quotas.items()}
    # B becomes the quality tier across retail markets once targeted quality is high enough.
    # Preserve a premium C premium while using the cheaper plans in new enterprise agreements.
    capacity = next((i for i, units in enumerate(CAPACITY) if units >= projected_usage), 7)
    operations = sum(i["new"] for i in stats["issues"] if "S" in i["group_id"])
    operations = int(max(2000, min(350000, max(operations/7*1.17, active*.055) / .30)) / 500) * 500
    global_dev = 25000 if day < 145 and len(estimates) >= 12 else 8000 if day < 330 else 0
    if remaining < 20:
        global_dev = 0
        dev = {g: x for g,x in dev.items() if quality.get(g,0) < 1.5}
    spend = sum(dev.values()) + sum(sum(a.values()) for a in advertising.values())+operations+global_dev
    allowable = max(8000, (.54*cash+.62*weekly_payment)/7)
    if spend > allowable:
        scale = max(.12, (allowable-operations-global_dev)/max(1,spend-operations-global_dev))
        dev = {g: int(x*scale/100)*100 for g,x in dev.items()}
        advertising = {ch:{g:int(x*scale/100)*100 for g,x in gs.items()} for ch,gs in advertising.items()}
    return dict(retail=retail, enterprise=enterprise, development=dev, global_development=global_dev, targeted_advertising=dict(advertising),
                operations=operations, capacity=capacity, models=models, quotas=quotas, ads_strength=ads_strength,
                average_revenue={g: m["sales"]/max(1,m["leads"]) for g,m in markets.items()},
                subs={g:m["subs"] for g,m in markets.items()}, efficiency=forecasts)

def cash_forecast(day, stats, policy, cash):
    market = breakdown(stats)
    daily = defaultdict(Counter)
    for r in stats["finance"]:
        daily[r["day"]][r["category"]] += r["amount"]
    mrr = sum(m["mrr"] for m in market.values())
    payments = [daily[i]["subscription_payment"] for i in range(max(1,day-6),day+1)]
    payment_daily = statistics.mean(payments)
    payment_sd = statistics.pstdev(payments) if len(payments) > 1 else max(1000,payment_daily*.2)
    latest = range(max(1,day-6),day+1)
    compute_daily = statistics.mean(-daily[i]["compute"] for i in latest)
    ads_daily = sum(sum(x.values()) for x in policy["targeted_advertising"].values())
    costs = (ads_daily + policy["operations"] + sum(policy["development"].values()) +
             policy["global_development"] + (85,215,530,1330,4000,10000,28000,75000)[policy["capacity"]])
    billing = rows("""SELECT billing_day_mod30 cycle,
        ROUND(SUM(seat_count*effective_price)) mrr FROM subscriptions
        WHERE status='subscribed' GROUP BY 1""")
    due = {r["cycle"]:r["mrr"] for r in billing}
    recent_first_period = max(0, sum(m["sales"] for m in market.values()) / 7)
    renewal_week = sum(due.get((day+d)%30,0) for d in range(1,8))
    curve = {}
    for k,h in (("1wk",7),("4wk",28),("12wk",84),("26wk",182)):
        projected_days = min(h,500-day)
        if projected_days <= 7:
            scheduled = sum(due.get((day+d)%30,0) for d in range(1,projected_days+1))
            income = .89*scheduled + projected_days*(recent_first_period*.93)
            income = .60*income + .40*payment_daily*projected_days
            cost = projected_days*(costs + compute_daily*(1.1 if day<125 else 1.025))
            delta = income-cost
        else:
            maturity = min(.95,max(.15,(day-50)/215))
            cashflow = max(.45*payment_daily, (mrr/30)*.93+min(recent_first_period*.80,payment_daily*.63))
            future_daily_cost = min(costs, max(.6*costs, costs-0.4*sum(policy["development"].values()))) + compute_daily
            near_delta = .5*(cashflow + payment_daily)-future_daily_cost
            growth = (1-maturity)*max(0, (.4*recent_first_period + (payment_daily-mrr/30)*.3))
            delta = projected_days*near_delta + growth*projected_days*min(2.5, projected_days/53)
        point = round(max(0,cash+delta))
        width = max(12000, payment_sd*math.sqrt(projected_days)*1.9,
                    abs(delta)*(.23+.014*h**.67),
                    max(mrr/30, recent_first_period)*projected_days*(.16 if h==7 else .23+.0015*h))
        curve["cash_"+k] = dict(point=point,lower=round(max(0,point-width)),upper=round(point+width))
    return curve

"""Advance this game's weekly strategy with public SDK observations."""
import json
from pathlib import Path
import re
import subprocess
import sys
import time

import novamind_api as nm

from strategy_enterprise import enterprise_offers
from strategy_metrics import snapshot, rows
from strategy_policy import breakdown, make_policy, cash_forecast

DIRECTORY = Path(__file__).resolve().parent
SESSION = "bc5a826aa613"
DAYS = 500

def read_json(name, fallback=None):
    filename = DIRECTORY / name
    if not filename.exists():
        return fallback
    return json.loads(filename.read_text())

def save_json(name, data):
    filename = DIRECTORY / name
    buffer = filename.with_suffix(".new")
    buffer.write_text(json.dumps(data))
    buffer.replace(filename)

def public_dashboard(week):
    completed = subprocess.run(
        [str(DIRECTORY/"novamind-operation"), "request-status", f"week-{week:03}", "--session", SESSION],
        check=True, capture_output=True, text=True)
    status = json.loads(completed.stdout)
    if status.get("status") != "completed" or not status.get("result", {}).get("success"):
        raise RuntimeError(f"Previous advance has no confirmed successful result: {status}")
    return status["result"]["dashboard"]

def quality_from(dashboard):
    shared = float(re.search(r"global_bonus=([-\d.]+)", dashboard)[1])
    bonuses = {}
    for line in dashboard.splitlines():
        m = re.match(r"^((?:D_)?[ES]\d+)\s+[-\d.]+\s+[-\d.]+\s+[-\d.]+\s+([-+\d.]+)\s*$",line)
        if m:
            bonuses[m[1]] = float(m[2])
    return {"shared":shared, **{g:.20+shared+bonus for g,bonus in bonuses.items()}}

def do(label, func, *args, **kwargs):
    result = func(*args, **kwargs)
    print(label, json.dumps(result, separators=(",", ":")), flush=True)
    return result

def estimates_now(existing):
    known = nm.market.get_market_overview()
    for group in known["known_groups"]:
        gid = group["group_id"]
        if gid not in existing:
            existing[gid] = nm.market.get_group_insights(gid)["estimates"]
    save_json("strategy_markets.json", existing)
    return known["undiscovered_count"]

def discovery(count, cap):
    for _ in range(cap):
        if count <= 0:
            break
        result = do("Discovery", nm.market.research_market)
        if result.get("discovered_group_id"):
            count -= 1

def research(day, cash, quality, projects):
    if day > 340 or cash < 8500000:
        return
    eligible = (10, 9, 8, 7)
    if day < 118 and quality.get("shared",0) < 1.45:
        eligible += (6, 5)
    remaining = DAYS-day
    allowed = 2 if cash < 26000000 else 4
    for row in sorted(projects, key=lambda r:r["tier"],reverse=True):
        tier = row["tier"]
        if tier not in eligible or row["in_progress"] or remaining < row["mean_days"]*1.35:
            continue
        if quality.get("shared",0) > 3.3 and day < 175:
            continue
        if quality.get("shared",0) > 4.6:
            continue
        do("Research", nm.research.start_research_project, tier)
        allowed -= 1
        if allowed == 0:
            return

def configure(policy, previous):
    prices = {p:max(r[i] for r in policy["retail"].values()) for i,p in enumerate("ABC")}
    discounts = {g:{p: round(prices[p]-r[i],2) for i,p in enumerate("ABC")} for g,r in policy["retail"].items()}
    if policy["retail"] != previous.get("retail"):
        do("Retail prices", nm.pricing.set_prices, **prices)
        do("Retail discounts", nm.pricing.set_promotion, by_group_plan=discounts)
    if policy["models"] != previous.get("models"):
        do("Model tiers", nm.pricing.set_model_tiers, **policy["models"])
    if policy["quotas"] != previous.get("quotas"):
        do("Usage quotas", nm.pricing.set_usage_quotas, **policy["quotas"])
    if policy["capacity"] != previous.get("capacity"):
        do("Capacity", nm.infrastructure.set_capacity_tier, policy["capacity"])
    if policy["operations"] != previous.get("operations") or policy["global_development"] != previous.get("global_development"):
        do("Daily spend", nm.marketing.set_daily_spend, operations=policy["operations"], development=policy["global_development"])
    if policy["development"] != previous.get("development"):
        do("Targeted development", nm.analytics.set_targeted_dev_spend, policy["development"])
    if policy["targeted_advertising"] != previous.get("targeted_advertising"):
        do("Customer acquisition", nm.marketing.set_targeted_ad_spend, policy["targeted_advertising"])
    if policy["ads_strength"] != previous.get("ads_strength"):
        do("In-app ads", nm.marketing.set_ads_strength, by_group=policy["ads_strength"])

def proactive(day, targets, quality):
    if day < 77 or day >= 475:
        return 0
    candidates = rows(f"""SELECT c.group_id,s.customer_id,s.plan,s.effective_price,s.seat_count
        FROM subscriptions s JOIN customers c USING(customer_id)
        WHERE s.status='subscribed' AND c.customer_type='large' AND c.contract_start_day<={day-21}
          AND s.seat_count>=100 AND NOT EXISTS
           (SELECT 1 FROM enterprise_turns e WHERE e.customer_id=s.customer_id AND e.day>{day-49})
        ORDER BY s.seat_count DESC LIMIT 1400""")
    benefits = []
    for c in candidates:
        g = c["group_id"]
        if g not in targets or quality.get(g,0) < 1.82:
            continue
        plan, target = targets[g]
        current = c["effective_price"]
        target = min(target, max(current+12,current*1.24))
        gain = target-current
        if plan < c["plan"]:
            gain += (1.3 if c["plan"]=="B" else 6)
        if gain >= 8 and target >= current-1:
            benefits.append((gain*c["seat_count"],c["customer_id"],plan,round(target,2)))
    chosen = sorted(benefits,reverse=True)[:85]
    if chosen:
        result = nm.enterprise.send_enterprise_deal([[cid,[[plan,price]]] for _,cid,plan,price in chosen])
        accepted = sum(bool(r.get("success")) for r in result.get("results",[]))
        print(f"Proactive offers {accepted}/{len(chosen)} sent with {sum(b[0] for b in chosen):,.0f} dollars in estimated monthly uplift", flush=True)
    return len(chosen)

def rationale(day, stats, policy, offers, prospective):
    market = breakdown(stats)
    retail = sum(m["subs"] for g,m in market.items() if "S" in g)
    seats = sum(m["seats"] for g,m in market.items() if "E" in g)
    subscription = sum(r["amount"] for r in stats["finance"] if r["category"]=="subscription_payment" and r["day"]>day-7)
    mrr = sum(m["mrr"] for m in market.values())
    top = ", ".join(f"{g} at {ratio:.1f}x" for g,ratio in sorted(policy["efficiency"].items(),key=lambda kv:kv[1],reverse=True)[:3])
    ad_spend = sum(sum(groups.values()) for groups in policy["targeted_advertising"].values())
    development = policy["global_development"] + sum(policy["development"].values())
    peak = max(r["total_usage_units"] for r in stats["service"])
    return (
        f"Day {day} cash was {stats['cash']:,.0f} dollars before new actions with {retail:,} retail subscribers, {seats:,} enterprise seats, "
        f"{subscription:,.0f} dollars in weekly collections and {mrr:,.0f} dollars in monthly subscription value. "
        f"Allocated {ad_spend:,.0f} dollars per day to acquisition using cohort collections per ad dollar"
        + (f" led by {top}. " if top else ". ")
        + f"Funded {development:,.0f} dollars per day in development where quality can still improve conversion and retention. "
        f"Quoted {offers} waiting enterprise accounts and {prospective} contracts with room for higher contribution. "
        f"Set capacity tier {policy['capacity']} from {peak:,} peak usage, and budgeted {policy['operations']:,.0f} dollars per day for support. "
        "Watch renewal receipts, lead conversion and operating margin after these changes."
    )

def run():
    day = nm.vars.current_day
    if day>=DAYS:
        print("Game already reached its terminal day.",flush=True)
        return
    if day % 7 != 0:
        raise RuntimeError(f"Unexpected current day {day}")
    week = day//7
    dashboard = public_dashboard(week)
    estimates = read_json("strategy_markets.json", {})
    while day < min(DAYS,read_json("strategy_end_day.json", DAYS)):
        if nm.vars.current_day != day:
            raise RuntimeError("Game day changed before the weekly decision.")
        quality = quality_from(dashboard)
        stats = snapshot(day)
        if stats["cash"] < 0:
            print(f"Bankruptcy on day {day} with {stats['cash']:,.2f} dollars", flush=True)
            return
        save_json(f"strategy_day{day}.json", {"day":day, "quality":quality, **stats})
        previous = read_json(f"strategy_plan{day-7}.json",{})
        config = rows("SELECT * FROM config_history ORDER BY day DESC LIMIT 1")[0]
        unknown_groups = estimates_now(estimates)
        policy = make_policy(day, stats, estimates, quality, previous, config)
        override = read_json(f"strategy_override{day}.json", {})
        policy.update(override)
        print(f"Day {day} committed cash {stats['cash']:,.2f} dollars, observations and plan ready for week {week+1}.",flush=True)
        save_json(f"strategy_plan{day}.json",policy)
        configure(policy,previous)
        if day < 106 and unknown_groups and stats["cash"] > 3500000:
            discovery(unknown_groups, 25 if stats["cash"]<16000000 else 48)
        projects = nm.research.list_research_projects()["tiers"] if day < 340 else []
        research(day,stats["cash"],quality,projects)
        enterprise_quality={g:quality.get(g,.2+quality.get("shared",0)) for g in policy["enterprise"]}
        offers = enterprise_offers(day, policy["enterprise"], enterprise_quality,
          {g:.83 if g not in ("E1","E2","E3") else .88 for g in policy["enterprise"]},limit=2800)
        seller = proactive(day,policy["enterprise"],quality)
        cash = rows("SELECT COALESCE(SUM(amount),0) cash FROM ledger")[0]["cash"]
        forecasts = cash_forecast(day,stats,policy,cash)
        explanation = rationale(day,stats,policy,offers,seller)
        print(explanation, json.dumps(forecasts),flush=True)
        request_id = f"week-{week+1:03}"
        started = time.monotonic()
        result = nm._client.next_week(rationale=explanation,predictions=forecasts,request_id=request_id)
        dashboard = result["dashboard"]
        new_day = result["day"]
        save_json(f"strategy_public_week{week+1:03}.json",result)
        print(dashboard,flush=True)
        print(f"{request_id} committed after {time.monotonic()-started:.1f}s",flush=True)
        if new_day != min(DAYS,day+7):
            print(f"Advance ended on day {new_day} before expected day {min(DAYS,day+7)}.",flush=True)
            return
        day = new_day
        week += 1

if __name__ == "__main__":
    try:
        run()
    except nm.NovaMindAPIError as exc:
        print(f"SDK request stopped the driver. Request ID {exc.request_id}, outcome {exc.outcome}. {exc}", file=sys.stderr,flush=True)
        sys.exit(2)

