    if last_usage>=235000000 and previous.get("quotas"):
        quotas = {p:min(q,previous["quotas"][p]+5) for p,q in quotas.items()}
    capacity = next((i for i, units in enumerate(CAPACITY) if units >= projected_usage), 7)
    incidence = sum(i["new"] for i in stats["issues"] if "S" in i["group_id"])/7
    backlog = sum(i["opened"] for i in stats["issues"] if "S" in i["group_id"])
    support = incidence*(1.25 if day<112 else 1.10) + max(0,backlog-incidence*1.5)/7
    operations = int(max(2000,min(350000,max(support,active*.025)/.29))/500)*500
