import re
import novamind_api as nm

def enterprise_offers(day, targets, quality, minimum_quality=None, limit=250, renewal_discount=0.03):
    minimum_quality = minimum_quality or {"E1": 0.59, "E2": 0.73, "E3": 0.82}
    candidates = nm.query(f"""SELECT c.group_id,e.customer_id,e.thread_type,e.sender,e.message_text,
        e.offer_json,e.turn_number,e.seat_count,e.day,s.plan,s.effective_price
        FROM enterprise_turns e JOIN customers c USING(customer_id)
        LEFT JOIN subscriptions s ON s.customer_id=e.customer_id AND s.status='subscribed'
        WHERE e.message_id IN
         (SELECT MAX(message_id) FROM enterprise_turns WHERE day > {day - 7} GROUP BY thread_id)
        AND e.closed=0 AND e.sender IN ('system','customer')
        ORDER BY CASE WHEN e.thread_type='new_lead' THEN 1 ELSE 0 END,e.seat_count DESC
        LIMIT {limit}""")["rows"]
    deals = []
    sample = []
    for row in candidates:
        group = row["group_id"]
        if group not in targets:
            continue
        plan, price = targets[group]
        if row["thread_type"] == "new_lead" and quality.get(group, 0) < minimum_quality.get(group, 0.70):
            continue
        try:
            structured = json.loads(row["offer_json"] or "{}")
        except ValueError:
            structured = {}
        suggested = structured.get("price_per_seat") or structured.get("price") if isinstance(structured,dict) else None
        if isinstance(suggested,(int,float)) and suggested>0:
            counter_plan = re.match(r"Counter-offer: Plan ([ABC]),",row["message_text"] or "")
            if suggested>price and counter_plan:
                price = min(price*2.20,suggested*.97)
                plan = counter_plan[1]
            else:
                price = min(price,max(.53*price,suggested*1.04))
        current = row["effective_price"]
        if row["thread_type"] in ("churn_prevention", "renewal"):
            if row["plan"] in ("A", "B", "C"):
                plan = max(plan, row["plan"])
            if current:
                ceiling = (1-renewal_discount)*current
                if isinstance(suggested,(int,float)) and suggested>current*1.15:
                    ceiling = current*1.12
                price = min(price,ceiling)
        price = max(1, floor(price * 100) / 100)
        deals.append([row["customer_id"], [[plan, price]]])
        if len(sample) < 5:
            sample.append([row["customer_id"], group, price, structured, row["message_text"][:150]])
    if deals:
        result = nm.enterprise.send_enterprise_deal(deals)
        successes = sum(bool(item.get("success")) for item in result.get("results", []))
        print(f"Enterprise offers {successes}/{len(deals)}; sample {json.dumps(sample)}", flush=True)
    return len(deals)

