DIRECTORY = Path(strategy_metrics.__file__).resolve().parent
SESSION = "bc5a826aa613"
DAYS = 500

def read_json(name, fallback=None):
    filename = DIRECTORY / name
    if not filename.exists():
        return fallback
    return json.loads(filename.read_text())

def save_json(name, data):
    filename = DIRECTORY / name
    buffer = filename.with_suffix(".new")
    buffer.write_text(json.dumps(data))
    buffer.replace(filename)

def public_dashboard(week):
    completed = subprocess.run(
        [str(DIRECTORY/"novamind-operation"), "request-status", f"week-{week:03}", "--session", SESSION],
        check=True, capture_output=True, text=True)
    status = json.loads(completed.stdout)
    if status.get("status") != "completed" or not status.get("result", {}).get("success"):
        raise RuntimeError(f"Previous advance has no confirmed successful result: {status}")
    return status["result"]["dashboard"]

def quality_from(dashboard):
    shared = float(re.search(r"global_bonus=([-\d.]+)", dashboard)[1])
    bonuses = {}
    for line in dashboard.splitlines():
        m = re.match(r"^((?:D_)?[ES]\d+)\s+[-\d.]+\s+[-\d.]+\s+[-\d.]+\s+([-+\d.]+)\s*$",line)
        if m:
            bonuses[m[1]] = float(m[2])
    return {"shared":shared, **{g:.20+shared+bonus for g,bonus in bonuses.items()}}

def do(label, func, *args, **kwargs):
    result = func(*args, **kwargs)
    print(label, json.dumps(result, separators=(",", ":")), flush=True)
    return result

def estimates_now(existing):
    known = nm.market.get_market_overview()
    for group in known["known_groups"]:
        gid = group["group_id"]
        if gid not in existing:
            existing[gid] = nm.market.get_group_insights(gid)["estimates"]
    save_json("strategy_markets.json", existing)
    return known["undiscovered_count"]

def discovery(count, cap):
    for _ in range(cap):
        if count <= 0:
            break
        result = do("Discovery", nm.market.research_market)
        if result.get("discovered_group_id"):
            count -= 1

def research(day, cash, quality, projects, policy):
    if day > 340 or cash < 8500000:
        return
    eligible = (10, 9, 8, 7)
    below_target = len(policy["development"]) >= 5 or policy["portfolio_conversion"] < .42
    if day < 310 and below_target:
        eligible += (6, 5)
    remaining = DAYS-day
    allowed = 2 if cash < 26000000 else 4
    for row in sorted(projects, key=lambda r:r["tier"],reverse=True):
        tier = row["tier"]
        if tier not in eligible or row["in_progress"] or remaining < row["mean_days"]*1.35:
            continue
        if quality.get("shared",0) > 3.3 and day < 175:
            continue
        if quality.get("shared",0) > (7.55 if below_target else 4.6):
            continue
        do("Research", nm.research.start_research_project, tier)
        allowed -= 1
        if allowed == 0:
            return

def configure(policy, previous):
    prices = {p:max(r[i] for r in policy["retail"].values()) for i,p in enumerate("ABC")}
    discounts = {g:{p: round(prices[p]-r[i],2) for i,p in enumerate("ABC")} for g,r in policy["retail"].items()}
    if policy["retail"] != previous.get("retail"):
        do("Retail prices", nm.pricing.set_prices, **prices)
        do("Retail discounts", nm.pricing.set_promotion, by_group_plan=discounts)
    if policy["models"] != previous.get("models"):
        do("Model tiers", nm.pricing.set_model_tiers, **policy["models"])
    if policy["quotas"] != previous.get("quotas"):
        do("Usage quotas", nm.pricing.set_usage_quotas, **policy["quotas"])
    if policy["capacity"] != previous.get("capacity"):
        do("Capacity", nm.infrastructure.set_capacity_tier, policy["capacity"])
    if policy["operations"] != previous.get("operations") or policy["global_development"] != previous.get("global_development"):
        do("Daily spend", nm.marketing.set_daily_spend, operations=policy["operations"], development=policy["global_development"])
    if policy.get("enterprise_support",{}) != previous.get("enterprise_support",{}):
        do("Enterprise support", nm.analytics.set_targeted_ops_spend, by_group=policy["enterprise_support"])
    if policy["development"] != previous.get("development"):
        do("Targeted development", nm.analytics.set_targeted_dev_spend, policy["development"])
    if policy["targeted_advertising"] != previous.get("targeted_advertising"):
        do("Customer acquisition", nm.marketing.set_targeted_ad_spend, policy["targeted_advertising"])
    if policy["ads_strength"] != previous.get("ads_strength"):
        do("In-app ads", nm.marketing.set_ads_strength, by_group=policy["ads_strength"])

def proactive(day, targets, quality):
    if day < 77 or day >= 475:
        return 0
    candidates = rows(f"""SELECT c.group_id,s.customer_id,s.plan,s.effective_price,s.seat_count
        FROM subscriptions s JOIN customers c USING(customer_id)
        WHERE s.status='subscribed' AND c.customer_type='large' AND c.contract_start_day<={day-21}
          AND s.seat_count>=100 AND NOT EXISTS
           (SELECT 1 FROM enterprise_turns e WHERE e.customer_id=s.customer_id AND e.day>{day-49})
        ORDER BY s.seat_count DESC LIMIT 1400""")
    benefits = []
    for c in candidates:
        g = c["group_id"]
        if g not in targets or quality.get(g,0) < 1.82:
            continue
        plan, target = targets[g]
        current = c["effective_price"]
        target = min(target, max(current+12,current*1.24))
        gain = target-current
        if plan < c["plan"]:
            gain += (1.3 if c["plan"]=="B" else 6)
        if gain >= 3 and gain*c["seat_count"]>=3600 and target >= current-1:
            benefits.append((gain*c["seat_count"],c["customer_id"],plan,round(target,2)))
    chosen = sorted(benefits,reverse=True)[:110]
    if chosen:
        result = nm.enterprise.send_enterprise_deal([[cid,[[plan,price]]] for _,cid,plan,price in chosen])
        accepted = sum(bool(r.get("success")) for r in result.get("results",[]))
        print(f"Proactive offers {accepted}/{len(chosen)} sent with {sum(b[0] for b in chosen):,.0f} dollars in estimated monthly uplift", flush=True)
    return len(chosen)

def rationale(day, stats, policy, offers, prospective):
    market = breakdown(stats)
    retail = sum(m["subs"] for g,m in market.items() if "S" in g)
    seats = sum(m["seats"] for g,m in market.items() if "E" in g)
    subscription = sum(r["amount"] for r in stats["finance"] if r["category"]=="subscription_payment" and r["day"]>day-7)
    mrr = sum(m["mrr"] for m in market.values())
    top = ", ".join(f"{g} at {ratio:.1f}x" for g,ratio in sorted(policy["efficiency"].items(),key=lambda kv:kv[1],reverse=True)[:3])
    ad_spend = sum(sum(groups.values()) for groups in policy["targeted_advertising"].values())
    development = policy["global_development"] + sum(policy["development"].values())
    peak = max(r["total_usage_units"] for r in stats["service"])
    return (
        f"Day {day} cash was {stats['cash']:,.0f} dollars before new actions with {retail:,} retail subscribers, {seats:,} enterprise seats, "
        f"{subscription:,.0f} dollars in weekly collections and {mrr:,.0f} dollars in monthly subscription value. "
        f"Allocated {ad_spend:,.0f} dollars per day to acquisition using cohort collections per ad dollar"
        + (f" led by {top}. " if top else ". ")
        + f"Funded {development:,.0f} dollars per day in development where quality can still improve conversion and retention. "
        f"Quoted {offers} waiting enterprise accounts and {prospective} contracts with room for higher contribution. "
        f"Set capacity tier {policy['capacity']} from {peak:,} peak usage, and budgeted {policy['operations']:,.0f} dollars per day for support. "
        f"Model tiers A/B/C are {'/'.join(str(tier) for tier in policy['models'].values())} based on delivered quality and inference costs. "
        + (f"Retail conversion was {policy['portfolio_conversion']:.1%}. Reduce in-app ads and prioritize quality and renewals while demand recovers. "
           if policy.get("recovery") else "")
        + ("Offer more competitive enterprise rates and higher delivered quality to recover seats and retain existing accounts. "
           if policy.get("enterprise_recovery") else "")
        + "Watch renewal receipts, lead conversion and operating margin after these changes."
    )

def run():
    day = nm.vars.current_day
    if day>=DAYS:
        print("Game already reached its terminal day.",flush=True)
        return
    if day % 7 != 0:
        raise RuntimeError(f"Unexpected current day {day}")
    week = day//7
    dashboard = public_dashboard(week)
    estimates = read_json("strategy_markets.json", {})
    while day < min(DAYS,read_json("strategy_end_day_v8.json", DAYS)):
        if nm.vars.current_day != day:
            raise RuntimeError("Game day changed before the weekly decision.")
        quality = quality_from(dashboard)
        stats = snapshot(day)
        if stats["cash"] < 0:
            print(f"Bankruptcy on day {day} with {stats['cash']:,.2f} dollars", flush=True)
            return
        save_json(f"strategy_day{day}.json", {"day":day, "quality":quality, **stats})
        previous = read_json(f"strategy_plan{day-7}.json",{})
        config = rows("SELECT * FROM config_history ORDER BY day DESC LIMIT 1")[0]
        unknown_groups = estimates_now(estimates)
        policy = make_policy(day, stats, estimates, quality, previous, config)
        if day in (105,203):
            try:
                posts = rows(f"""SELECT day, content FROM social_media_posts WHERE day>{day-21}
                    AND (LOWER(content) LIKE '%competitor%' OR LOWER(content) LIKE '%launches%'
                    OR LOWER(content) LIKE '%introduces%' OR LOWER(content) LIKE '%rival%')
                    ORDER BY day DESC LIMIT 15""")
                save_json(f"strategy_public_market_comments{day}.json",posts)
                for post in posts[:5]:
                    print("Public market comment", json.dumps(post), flush=True)
            except nm.NovaMindAPIError as exc:
                print(f"Public market comments query failed. Continuing with cohort and service results. {exc}",flush=True)
        override = read_json(f"strategy_override{day}.json", {})
        policy.update(override)
        print(f"Day {day} committed cash {stats['cash']:,.2f} dollars, observations and plan ready for week {week+1}.",flush=True)
        save_json(f"strategy_plan{day}.json",policy)
        configure(policy,previous)
        if day < 106 and unknown_groups and stats["cash"] > 3500000:
            discovery(unknown_groups, 25 if stats["cash"]<16000000 else 48)
        projects = nm.research.list_research_projects()["tiers"] if day < 340 else []
        research(day,stats["cash"],quality,projects,policy)
        enterprise_quality={g:quality.get(g,.2+quality.get("shared",0)) for g in policy["enterprise"]}
        offers = enterprise_offers(day, policy["enterprise"], enterprise_quality,
          {g:.83 if g not in ("E1","E2","E3") else .88 for g in policy["enterprise"]},limit=3600,
          renewal_discount=.065 if policy.get("enterprise_recovery") else .03)
        seller = 0 if policy.get("enterprise_recovery") else proactive(day,policy["enterprise"],quality)

