"""Summarize the public status and latest request for the one CEOBench session."""
import json
from pathlib import Path
import re
import subprocess

ROOT = Path(__file__).resolve().parent
OPERATION = ROOT / "novamind-operation"
SESSION = "bc5a826aa613"

def public_cli(*args):
    result = subprocess.run(
        [str(OPERATION), *args, "--session", SESSION],
        capture_output=True, text=True, check=True)
    return json.loads(result.stdout)

def current_status():
    info = public_cli("status")
    print(f"Day {info['current_day']} | committed cash {info['cash']:,.2f} dollars | "
          f"{info['status']} | server running {info['server_running']}")
    transcripts = [p for p in ROOT.glob("strategy_batch*.txt") if p.stat().st_size]
    if not transcripts:
        return
    transcripts.sort(key=lambda p: int(p.stem.removeprefix("strategy_batch")))
    lines = transcripts[-1].read_text().splitlines()
    for line in lines[-25:]:
        if re.search(r'(^Traceback|Error:|stopped the driver)', line):
            print(line)
    ids = sorted(set(
        rid for path in transcripts
        for rid in re.findall(r'\{"request_id": "(week-\d+)"\}', path.read_text())
    ))
    interruption = re.search(r'SDK request stopped the driver. Request ID ([a-z0-9-]+),', "\n".join(lines[-8:]))
    if interruption:
        ids.append(interruption[1])
    if ids:
        state = public_cli("request-status", ids[-1])
        result = state.get("result", {})
        print(f"{ids[-1]} | {state.get('status')}" + (f" | day {result.get('day')}" if result.get("day") else ""))
        if result and not result.get("success"):
            print(json.dumps(result))

if __name__ == "__main__":
    current_status()

